# 【算法思路】通过关键词命中率判别客服意图、正则抽取手机订单与商品实体并填表生成个性化回复。
import re
# 依据意图词表命中计数挑选最佳意图与置信度
def classify_intent(text, categories):
    text_lower = text.lower()
    best_cat = None; best_score = 0
    for cat, keywords in categories.items():
        score = sum(1 for kw in keywords if kw.lower() in text_lower)
        if score > best_score:
            best_score = score; best_cat = cat
    return {'intent': best_cat, 'confidence': round(best_score / max(best_score,1), 2)}
# 正则提取两字母八数字订单号及核心品类商品名
def extract_entities(text):
    order_pattern = r'[A-Z]{2}\d{8}'
    orders = re.findall(order_pattern, text)
    product_pattern = r'(手机|电脑|耳机|鼠标|键盘|充电器)'
    products = re.findall(product_pattern, text)
    return {'order_ids': orders, 'products': products}
# 使用抽取到的实体字典格式化渲染意图答复模板
def generate_response(intent, entities, templates):
    template = templates.get(intent, '感谢您的咨询，我们已收到您的请求。')
    return template.format(**entities)

# 【算法思路】解析光标字节偏移所在代码行号和缩进深度，再依关键词匹配相关代码片段排序提供智能补全。
# 定位当前行字符串、缩进空格数以及前一行上下文
def extract_context(code, pos):
    lines = code.split('\n')
    line_idx = code[:pos].count('\n')
    cur_line = lines[line_idx] if line_idx < len(lines) else ''
    indent = len(cur_line) - len(cur_line.lstrip())
    prev_line = lines[line_idx-1] if line_idx > 0 else ''
    return {'line': cur_line, 'indent': indent, 'prev_line': prev_line, 'line_idx': line_idx}
# 按相关度得分降序推荐至多前 5 个候选补全块
def suggest_completions(context, snippets):
    scored = []
    for s in snippets:
        score = calculate_relevance(context, s)
        if score > 0:
            scored.append((score, s))
    scored.sort(key=lambda x:-x[0])
    return [s for _, s in scored[:5]]
# 统计当前行中包含代码片段关键字的命中数目
def calculate_relevance(context, snippet):
    score = 0
    for kw in snippet.get('keywords', []):
        if kw.lower() in context['line'].lower():
            score += 1
    return score

