# 【算法思路】依据自然语言任务中的动作关键词拆解原子步骤流，再结合智能体能力匹配和余力均衡指派。
# 识别数据、分析、报告与图表动词生成执行子任务列表
def decompose_task(task,capabilities):
    steps=[]
    if "data" in task.lower():steps.append("fetch_data")
    if "analy" in task.lower():steps.append("analyze")
    if "report" in task.lower() or "summar" in task.lower():steps.append("generate_report")
    if "plot" in task.lower() or "chart" in task.lower():steps.append("visualize")
    if not steps:steps.append("process")
    return steps
# 在能胜任的子智能体中优先调度当前剩余算力最充足者并扣减负载
def assign_subtasks(subtasks,agents):
    assignment={}
    for st in subtasks:
        best=None;best_score=-1
        for a_name,skills in agents.items():
            if st in skills["can_do"] and skills["workload"]>best_score:
                best=a_name;best_score=skills["workload"]
        if best:
            assignment[st]=best
            agents[best]["workload"]-=1
        else:assignment[st]="unassigned"
    return assignment

# 【算法思路】模拟参数滑块即时驱动的交互式模型控制台：构建输入规范、计算逻辑回归概率输出及记录用户反馈。
import json
# 声明交互界面入参清单与在线实时就绪配置
def build_demo(model,input_schema):
    return {"model":model,"inputs":input_schema,"outputs":["prediction","confidence"],"live":True}
# 依据当前滑块特征向量与权重内积输出概率置信度
def update_plot(params,model):
    import math
    pred=sum(v*k for v,k in zip(params,model))if params else 0
    return {"prediction":round(pred,3),"confidence":round(1/(1+math.exp(-pred)),3)}
# 将用户校正样本对标注为已日志归档
def process_feedback(ui,mo):
